public void drawString(int x, int y) {
			if(info == null || info.isEmpty())
				return;

			drawHoveringText(Arrays.asList(new String[] { info }), x, y);
		}

public void drawString(int x, int y) {
			if(info == null || info.isEmpty())
				return;

			String s = info;

			drawHoveringText(Arrays.asList(new String[] { s }), x, y);
		}

public void drawString(int x, int y) {
			if(info == null || info.isEmpty())
				return;

			if(stack != null) {
				GUIScreenTemplateFolder.this.renderToolTip(stack, x, y);
			} else {
				drawHoveringText(Arrays.asList(new String[] { info }), x, y);
			}
		}

public void drawCustomInfoStat(int mouseX, int mouseY, int x, int y, int width, int height, int tPosX, int tPosY, String[] text) {

		if(x <= mouseX && x + width > mouseX && y < mouseY && y + height >= mouseY)
			this.drawHoveringText(Arrays.asList(text), tPosX, tPosY);
	}
